for o in "$@"; do node work/somerville/diag/tube-diag.mjs "$o" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const j=JSON.parse(s);console.log(JSON.stringify(j.opts),"seedPen",j.seed.pen,"gap",j.seed.gap?.toFixed(5),"self",j.tube.self,"fold",j.tube.folded,"col",j.tube.col,Object.keys(j.pairs).slice(0,4).join(";"),j.foldedSegs.slice(0,3),j.tight,"opsFail",Object.entries(j.ops).filter(([,v])=>!v).map(([k])=>k))})'; done
